begin;
create table public.schedule_venues (
  name text primary key check (length(name) between 1 and 100 and name = btrim(name)),
  created_at timestamptz not null default now()
);
create table public.schedule_events (
  id uuid primary key default gen_random_uuid(),
  event_date date not null check (event_date between date '2000-01-01' and date '2100-12-31'),
  end_date date not null,
  kind text not null check (kind in ('visit','banner')),
  venue text references public.schedule_venues(name),
  title text not null default '' check (length(title) <= 200),
  calendar_text text not null default '' check (length(calendar_text) <= 80),
  emoji text not null default '' check (length(emoji) <= 20),
  start_time time,
  version integer not null default 1,
  deleted_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (end_date >= event_date and end_date - event_date <= 366),
  check ((kind='visit' and venue is not null and end_date=event_date) or (kind='banner' and venue is null and length(btrim(title)) > 0))
);
create unique index schedule_events_active_unique on public.schedule_events
  (event_date,end_date,kind,coalesce(venue,''),title,coalesce(start_time,time '00:00')) where deleted_at is null;
alter table public.schedule_venues enable row level security;
alter table public.schedule_events enable row level security;
create policy schedule_venues_public_read on public.schedule_venues for select to anon, authenticated using (true);
create policy schedule_events_public_read on public.schedule_events for select to anon, authenticated using (deleted_at is null);
revoke all on public.schedule_venues, public.schedule_events from anon, authenticated;
grant select on public.schedule_venues, public.schedule_events to anon, authenticated;

-- Reuse the existing server-side password check with an empty, non-writing batch.
create function public.admin_check_password(input_password text) returns boolean
language plpgsql security definer set search_path = public as $$
begin
  perform public.admin_add_points(input_password, '[]'::jsonb, null::text, current_date);
  return true;
end $$;
create function public.admin_save_schedule(input_password text, p_id uuid, p_version integer,
  p_date date, p_end_date date, p_kind text, p_venue text, p_title text,
  p_calendar_text text, p_emoji text, p_start_time time) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_row public.schedule_events; v_venue text;
begin
  perform public.admin_check_password(input_password);
  if p_date is null or p_date < date '2000-01-01' or p_date > date '2100-12-31'
    or p_end_date is null or p_end_date < p_date or p_end_date-p_date > 366
    or p_kind is null or p_kind not in ('visit','banner') then raise exception 'INVALID_SCHEDULE'; end if;
  if p_kind='visit' then
    v_venue := regexp_replace(btrim(p_venue), '\s+', ' ', 'g');
    if v_venue is null or length(v_venue) not between 1 and 100 or p_end_date<>p_date then raise exception 'INVALID_VENUE'; end if;
    insert into public.schedule_venues(name) values(v_venue) on conflict do nothing;
  elsif length(btrim(coalesce(p_title,'')))=0 then raise exception 'TITLE_REQUIRED';
  end if;
  if p_id is null then
    insert into public.schedule_events(event_date,end_date,kind,venue,title,calendar_text,emoji,start_time)
    values(p_date,p_end_date,p_kind,v_venue,case when p_kind='visit' then '' else btrim(p_title) end,
      case when p_kind='visit' then '' else btrim(coalesce(p_calendar_text,'')) end,
      case when p_kind='visit' then '' else coalesce(p_emoji,'') end,p_start_time) returning * into v_row;
  else
    update public.schedule_events set event_date=p_date,end_date=p_end_date,kind=p_kind,venue=v_venue,
      title=case when p_kind='visit' then '' else btrim(p_title) end,
      calendar_text=case when p_kind='visit' then '' else btrim(coalesce(p_calendar_text,'')) end,
      emoji=case when p_kind='visit' then '' else coalesce(p_emoji,'') end,start_time=p_start_time,
      version=version+1,updated_at=now()
    where id=p_id and version=p_version and deleted_at is null returning * into v_row;
    if not found then raise exception 'SCHEDULE_CHANGED'; end if;
  end if;
  return to_jsonb(v_row);
end $$;
create function public.admin_delete_schedule(input_password text,p_id uuid,p_version integer) returns boolean
language plpgsql security definer set search_path = public as $$
begin
  perform public.admin_check_password(input_password);
  update public.schedule_events set deleted_at=now(),updated_at=now(),version=version+1
    where id=p_id and version=p_version and deleted_at is null;
  if not found then raise exception 'SCHEDULE_CHANGED'; end if;
  return true;
end $$;
revoke all on function public.admin_check_password(text) from public;
revoke all on function public.admin_save_schedule(text,uuid,integer,date,date,text,text,text,text,text,time) from public;
revoke all on function public.admin_delete_schedule(text,uuid,integer) from public;
grant execute on function public.admin_check_password(text) to anon,authenticated;
grant execute on function public.admin_save_schedule(text,uuid,integer,date,date,text,text,text,text,text,time) to anon,authenticated;
grant execute on function public.admin_delete_schedule(text,uuid,integer) to anon,authenticated;

